1	package store
2	
3	import (
4		"context"
5	
6		storepb "github.com/usememos/memos/proto/gen/store"
7	)
8	
9	// DeleteUserFailpoint is a test-only hook for forcing a delete-user rollback.
10	type DeleteUserFailpoint string
11	
12	const (
13		// DeleteUserFailpointBeforeCommit aborts after all delete statements run but before commit.
14		DeleteUserFailpointBeforeCommit DeleteUserFailpoint = "before_commit"
15	)
16	
17	type deleteUserFailpointKey struct{}
18	
19	// DeleteUserResult contains resources collected while deleting a user.
20	type DeleteUserResult struct {
21		Attachments     []*Attachment
22		UserSettingKeys []storepb.UserSetting_Key
23	}
24	
25	// WithDeleteUserFailpoint is a test-only helper that forces DeleteUser to roll back.
26	func WithDeleteUserFailpoint(ctx context.Context, failpoint DeleteUserFailpoint) context.Context {
27		return context.WithValue(ctx, deleteUserFailpointKey{}, failpoint)
28	}
29	
